<script setup lang="ts">
import PlanResults from "./PlanResults.vue"
import GlassPlanner from './GlassPlanner.vue'
import { newId } from "../id"
import { ElMessage } from 'element-plus'
import { ref, computed, watch, nextTick } from 'vue'
import { Plus, Trash2, Scissors, Download, Printer } from 'lucide-vue-next'
import { useWorkshop } from '../store'
import { mm, money, T } from '../types'
import LengthInput from './LengthInput.vue'
import { download, csv } from '../export'
const s=useWorkshop(),cutTab=ref('profile'),glassEditor=ref<InstanceType<typeof GlassPlanner>>()
async function applyPending(){if(!s.glassDraftDirty)return true;cutTab.value='glass';await nextTick();return await glassEditor.value?.apply()??false}
defineExpose({applyPending})
const printPlan=()=>window.print()
function jumpTo(id:string){document.getElementById(id)?.scrollIntoView({block:'start',behavior:'smooth'})}
watch(()=>s.plan,async value=>{if(value&&cutTab.value==='profile'){await nextTick();jumpTo('profile-result')}})
const keys=computed(()=>[...new Set([...Object.values(s.project!.profiles).map(p=>p.stock_key),...s.stocks.map(p=>p.stock_key)])])
const required=computed(()=>[...new Set(s.geometry!.parts.map(p=>p.stock_key))])
const missing=computed(()=>required.value.filter(key=>!s.stocks.some(stock=>stock.stock_key===key)))
const unavailable=computed(()=>required.value.filter(key=>s.stocks.some(stock=>stock.stock_key===key)&&!s.stocks.some(stock=>stock.stock_key===key&&stock.available!==0)))
function describe(key:string){const names=[...new Set(s.geometry!.parts.filter(p=>p.stock_key===key).map(p=>p.category_label))];return names.length?`${names.join(' / ')}（${key}）`:key}
function supplement(){
  const additions=missing.value.map(key=>({id:'示例-'+newId(),stock_key:key,length:6000*T,price_cents:0,available:null}))
  s.stocks.push(...additions);s.error='';s.invalidate();s.persist()
  ElMessage.success(`已补充 ${additions.length} 种型号，请核对示例长度 6000 mm 并填写实际规格`)
}
watch([()=>s.stocks,()=>s.settings],()=>{s.invalidate();s.persist()},{deep:true})
function add(){s.stocks.push({id:newId(),stock_key:missing.value[0]??keys.value[0]!,length:6000*T,price_cents:0,available:null})}
function exportPlan(){if(s.plan)download(`${s.project!.name}-切割方案.json`,JSON.stringify({project:s.project,stocks:s.stocks,settings:s.settings,result:s.plan},null,2))}
function exportCuts(){if(s.plan)download(`${s.project!.name}-逐根切割.csv`,csv([['原料根号','型号','规格mm','次序','构件实例','类别','长边mm','短边mm','角度','毛坯区间起mm','毛坯区间止mm','前锯缝mm','后锯缝mm'],...s.plan.groups.flatMap(g=>g.bars.flatMap(b=>b.pieces.map((p,i)=>[b.id,b.stock_key,mm(b.length),i+1,p.instance,p.category,mm(p.length),mm(p.short_length),p.angle,mm(p.from_tick),mm(p.to_tick),mm(p.front_loss),mm(p.back_loss)])))]),'text/csv;charset=utf-8')}
</script>
<template><div class="cutting-view"><el-tabs v-model="cutTab" class="workspace-tabs no-print" aria-label="排料类型"><el-tab-pane label="型材排料" name="profile"/><el-tab-pane label="玻璃排料" name="glass"/></el-tabs><el-alert v-if="s.glassDraftDirty&&cutTab==='profile'" title="玻璃参数尚未应用，切换回玻璃排料即可继续编辑。" type="warning" :closable="false"/><GlassPlanner ref="glassEditor" v-show="cutTab==='glass'"/><div v-show="cutTab==='profile'" class="profile-planner"><div v-if="missing.length||unavailable.length" class="panel no-print"><el-alert type="warning" :closable="false" title="型材原料规格尚未匹配，玻璃排料不受影响"/><p v-if="missing.length" class="muted">缺少规格：{{missing.map(describe).join('、')}}。窗型型号必须与下方原料型号一致。</p><p v-if="unavailable.length" class="muted">可用数量全为 0：{{unavailable.map(describe).join('、')}}。请按实际库存修改数量；留空表示可采购、不限量。</p><el-button v-if="missing.length" @click="supplement">补充缺失规格（示例长度 6000 mm）</el-button></div><div class="panel-heading no-print"><h2>型材采购与一维切割</h2></div><div class="planner-shortcuts no-print"><el-button @click="jumpTo('profile-stocks')">原料规格</el-button><el-button @click="jumpTo('profile-settings')">工艺设置</el-button><el-button v-if="s.plan" @click="jumpTo('profile-result')">查看方案</el-button><el-button type="primary" :loading="s.solving" :disabled="s.busy||!!missing.length||!!unavailable.length" @click="s.solve">计算型材方案</el-button></div>
<section id="profile-stocks" class="panel stock-panel no-print"><div class="panel-heading"><div><span class="eyebrow">STOCK LIBRARY</span><h2>原料规格</h2></div><el-button @click="add"><Plus :size="15"/> 添加规格</el-button></div>
<p class="muted">同一型号可添加多种长度；只有型号相同的构件才会合并排料。数量留空表示可采购、不限量。</p>
<el-table class="desktop-data" :data="s.stocks" max-height="340" size="small"><el-table-column label="规格编号" width="150"><template #default="{row}"><el-input v-model="row.id" aria-label="原料规格编号"/></template></el-table-column><el-table-column label="原料型号" min-width="180"><template #default="{row}"><el-select v-model="row.stock_key" aria-label="原料型号"><el-option v-for="key in keys" :key="key" :value="key" :label="describe(key)"/></el-select></template></el-table-column><el-table-column label="整料长度" width="160"><template #default="{row}"><LengthInput v-model="row.length" :min="2" label="整料长度"/></template></el-table-column><el-table-column label="单价 / 元" width="150"><template #default="{row}"><el-input-number :model-value="row.price_cents/100" :min="0" :max="100000" :precision="2" :controls="false" @update:model-value="(v:number|undefined)=>row.price_cents=Math.round((v??0)*100)"/></template></el-table-column><el-table-column label="可用根数" width="140"><template #default="{row}"><el-input-number :model-value="row.available" :min="0" :max="500" :precision="0" :controls="false" placeholder="不限" @update:model-value="(v:number|undefined)=>row.available=v??null"/></template></el-table-column><el-table-column width="50"><template #default="{row}"><el-button text type="danger" aria-label="删除原料规格" @click="s.stocks=s.stocks.filter(x=>x!==row)"><Trash2 :size="15"/></el-button></template></el-table-column></el-table>
<div class="mobile-data stock-cards"><details v-for="(row,index) in s.stocks" :key="index" class="mobile-card stock-detail"><summary><b>{{row.stock_key||'未选择型号'}}</b><span>{{Number.isFinite(row.length)?mm(row.length)+' mm':'尺寸待修正'}} · {{row.available==null?'不限量':row.available+' 根'}}</span><small>展开编辑规格</small></summary><div class="card-title"><b>原料规格 {{index+1}}</b><el-button text type="danger" aria-label="删除原料规格" @click="s.stocks.splice(index,1)"><Trash2 :size="18"/>删除</el-button></div><el-form label-position="top"><el-form-item label="规格编号"><el-input v-model="row.id" aria-label="原料规格编号"/></el-form-item><el-form-item label="原料型号"><el-select v-model="row.stock_key" aria-label="原料型号"><el-option v-for="key in keys" :key="key" :value="key" :label="describe(key)"/></el-select></el-form-item><el-form-item label="整料长度"><LengthInput v-model="row.length" :min="2" label="整料长度"/></el-form-item><div class="two-cols"><el-form-item label="单价 / 元"><el-input-number :model-value="row.price_cents/100" :min="0" :max="100000" :precision="2" :controls="false" @update:model-value="(v:number|undefined)=>row.price_cents=Math.round((v??0)*100)"/></el-form-item><el-form-item label="可用根数"><el-input-number :model-value="row.available" :min="0" :max="500" :precision="0" :controls="false" placeholder="不限" @update:model-value="(v:number|undefined)=>row.available=v??null"/></el-form-item></div></el-form></details></div></section>
<section id="profile-settings" class="panel no-print"><div class="panel-heading"><div><span class="eyebrow">CUTTING RULES</span><h2>切割工艺与目标</h2></div><el-tag effect="plain">独立双端斜切 · 保守用料</el-tag></div>
<el-form label-position="top" :model="s.settings" class="cut-settings"><el-form-item label="刀片厚度"><LengthInput v-model="s.settings.kerf" label="刀片厚度"/></el-form-item><el-form-item label="每根原料头部修整（含锯缝）"><LengthInput v-model="s.settings.trim_start" label="头部修整"/></el-form-item><el-form-item label="每根原料尾部修整（含锯缝）"><LengthInput v-model="s.settings.trim_end" label="尾部修整"/></el-form-item><el-form-item label="优化目标"><el-select v-model="s.settings.objective"><el-option value="bars" label="最少根数，其次最少购料长度"/><el-option value="cost" label="最低采购金额，其次最少根数"/></el-select></el-form-item><el-form-item label="可回收余料最短长度"><LengthInput v-model="s.settings.reusable_min" label="可回收余料最短长度"/></el-form-item><el-form-item label="每个型号求解时限"><el-select v-model="s.settings.time_limit"><el-option v-for="n in [3,10,30]" :key="n" :value="n" :label="`${n} 秒`"/></el-select></el-form-item></el-form>
<div class="rule-note">直切每根预留 1 道锯缝；45° 外框每根预留 2 道斜切锯缝，每道按 √2 × 刀片厚度向上取整。默认不共用斜口、不嵌套尖角。同等采购方案下优先减少短废料，再集中长余料。余料达到设定长度即列为可回收，不自动加入库存。</div>
<div class="solve-action"><span class="muted">{{s.solving?'正在求解各型号；修改参数会使本次结果失效。':'按当前窗型清单重新计算，全部构件必须完整覆盖。'}}</span><el-button type="primary" size="large" :loading="s.solving" :disabled="s.busy||!!missing.length||!!unavailable.length" @click="s.solve"><Scissors v-if="!s.solving" :size="17"/> 计算采购与切割方案</el-button></div>
</section>
<PlanResults v-if="s.plan" :plan="s.plan" :title="s.project!.name" :priced="s.stocks.every(x=>x.supply==='inventory'||x.price_cents>0)"/>
<section v-else class="empty-plan"><Scissors :size="32"/><h3>把每一根原料，安排得更合适</h3><p>完善原料规格后开始计算，生成采购清单和逐根切割示意。</p></section>
</div></div></template>
